import os
import shutil
import ctypes
from dataclasses import dataclass, field
from pathlib import Path
from typing import Callable


ConflictResolver = Callable[[Path, Path], str]


@dataclass
class OperationFailure:
    source: Path
    target: Path | None
    message: str


@dataclass
class OperationResult:
    completed: list[Path] = field(default_factory=list)
    skipped: list[Path] = field(default_factory=list)
    failures: list[OperationFailure] = field(default_factory=list)

    @property
    def successful(self) -> bool:
        return not self.failures and not self.skipped


def unique_target(target: Path) -> Path:
    if not target.exists():
        return target
    for number in range(2, 10000):
        candidate = target.with_name(f"{target.stem} ({number}){target.suffix}")
        if not candidate.exists():
            return candidate
    raise FileExistsError(f"Cannot find an available name for {target.name}")


def _remove_existing(path: Path) -> None:
    if path.is_dir() and not path.is_symlink():
        shutil.rmtree(path)
    else:
        path.unlink()


def _copy_or_move(source: Path, target: Path, move: bool) -> None:
    if move:
        shutil.move(str(source), str(target))
    elif source.is_dir():
        shutil.copytree(source, target)
    else:
        shutil.copy2(source, target)


def _replace_transactional(source: Path, target: Path, move: bool) -> None:
    backup = unique_target(target.with_name(f".{target.name}.pfc-backup"))
    target.rename(backup)
    try:
        _copy_or_move(source, target, move)
    except (OSError, shutil.Error):
        try:
            if target.exists(): _remove_existing(target)
            backup.rename(target)
        except OSError:
            pass
        raise
    try:
        _remove_existing(backup)
    except OSError:
        pass  # The new item is valid; preserve the old backup rather than risking either copy.


def transfer_items(items: list[Path], destination: Path, move: bool = False,
                   resolve_conflict: ConflictResolver | None = None,
                   continue_on_error: bool = True) -> OperationResult:
    destination.mkdir(parents=True, exist_ok=True)
    result = OperationResult()
    for index, source in enumerate(items):
        target = destination / source.name
        try:
            source_resolved, target_resolved = source.resolve(), target.resolve()
            replace = False
            if source.is_dir() and source_resolved in target_resolved.parents:
                raise OSError("A folder cannot be copied or moved into itself.")
            if target.exists():
                action = resolve_conflict(source, target) if resolve_conflict else "replace"
                if action == "cancel":
                    result.skipped.extend(items[index:])
                    break
                if action == "skip":
                    result.skipped.append(source)
                    continue
                if action == "keep_both":
                    target = unique_target(target)
                elif action == "replace":
                    if source_resolved == target_resolved:
                        raise OSError("Source and destination are the same item. Choose Keep Both or Skip.")
                    replace = True
                else:
                    raise ValueError(f"Unknown conflict action: {action}")
            if replace:
                _replace_transactional(source, target, move)
            else:
                _copy_or_move(source, target, move)
            result.completed.append(source)
        except (OSError, shutil.Error, ValueError) as exc:
            result.failures.append(OperationFailure(source, target, str(exc)))
            if not continue_on_error:
                result.skipped.extend(items[index + 1:])
                break
    return result


def copy_items(items: list[Path], destination: Path,
               resolve_conflict: ConflictResolver | None = None,
               continue_on_error: bool = True) -> OperationResult:
    return transfer_items(items, destination, move=False, resolve_conflict=resolve_conflict,
                          continue_on_error=continue_on_error)


def move_items(items: list[Path], destination: Path,
               resolve_conflict: ConflictResolver | None = None,
               continue_on_error: bool = True) -> OperationResult:
    return transfer_items(items, destination, move=True, resolve_conflict=resolve_conflict,
                          continue_on_error=continue_on_error)


def delete_items(items: list[Path], continue_on_error: bool = True) -> OperationResult:
    result = OperationResult()
    for item in items:
        try:
            _remove_existing(item)
            result.completed.append(item)
        except OSError as exc:
            result.failures.append(OperationFailure(item, None, str(exc)))
            if not continue_on_error:
                result.skipped.extend(items[len(result.completed) + len(result.failures):])
                break
    return result


class _SHFILEOPSTRUCTW(ctypes.Structure):
    _fields_ = [("hwnd", ctypes.c_void_p), ("wFunc", ctypes.c_uint),
                ("pFrom", ctypes.c_wchar_p), ("pTo", ctypes.c_wchar_p),
                ("fFlags", ctypes.c_ushort), ("fAnyOperationsAborted", ctypes.c_int),
                ("hNameMappings", ctypes.c_void_p), ("lpszProgressTitle", ctypes.c_wchar_p)]


def recycle_items(items: list[Path], continue_on_error: bool = True) -> OperationResult:
    result = OperationResult()
    if os.name != "nt":
        return OperationResult(failures=[OperationFailure(item, None, "Recycle Bin requires Windows.")
                                         for item in items])
    shell32 = ctypes.windll.shell32
    kernel32 = ctypes.windll.kernel32
    kernel32.GetDriveTypeW.argtypes = [ctypes.c_wchar_p]
    kernel32.GetDriveTypeW.restype = ctypes.c_uint
    shell32.SHFileOperationW.argtypes = [ctypes.POINTER(_SHFILEOPSTRUCTW)]
    shell32.SHFileOperationW.restype = ctypes.c_int
    for item in items:
        if str(item).startswith("\\\\") or (item.anchor and kernel32.GetDriveTypeW(str(item.anchor)) == 4):
            result.failures.append(OperationFailure(
                item, None, "Network locations do not provide a safe Windows Recycle Bin. Use Shift+Del explicitly."))
            if not continue_on_error:
                result.skipped.extend(items[len(result.completed) + len(result.failures):])
                break
            continue
        operation = _SHFILEOPSTRUCTW(None, 3, str(item.resolve()) + "\0\0", None,
                                     0x40 | 0x10 | 0x04 | 0x400, 0, None, None)
        code = shell32.SHFileOperationW(ctypes.byref(operation))
        if code == 0 and not operation.fAnyOperationsAborted:
            result.completed.append(item)
        else:
            message = "Recycle operation was cancelled." if operation.fAnyOperationsAborted else f"Windows error 0x{code:04X}"
            result.failures.append(OperationFailure(item, None, message))
            if not continue_on_error:
                result.skipped.extend(items[len(result.completed) + len(result.failures):])
                break
    return result


def format_size(size: int) -> str:
    value = float(size)
    for unit in ("B", "KB", "MB", "GB", "TB"):
        if value < 1024 or unit == "TB":
            return f"{value:.0f} {unit}" if unit == "B" else f"{value:.1f} {unit}"
        value /= 1024
    return str(size)


def roots() -> list[Path]:
    if os.name != "nt":
        return [Path("/")]
    return [Path(f"{letter}:\\") for letter in "ABCDEFGHIJKLMNOPQRSTUVWXYZ" if Path(f"{letter}:\\").exists()]


def is_system(path: Path) -> bool:
    """Return whether Windows marks a path with the SYSTEM attribute."""
    if os.name != "nt":
        return False
    attributes = ctypes.windll.kernel32.GetFileAttributesW(str(path))
    return attributes != 0xFFFFFFFF and bool(attributes & 0x4)


import ctypes
import os
import shutil
import struct
import time
from dataclasses import dataclass
from pathlib import Path


CF_HDROP = 15
GMEM_MOVEABLE_ZEROINIT = 0x0042
DROPEFFECT_COPY = 1
DROPEFFECT_MOVE = 2
TYMED_HGLOBAL = 1
TYMED_FILE = 2
TYMED_ISTREAM = 4
DVASPECT_CONTENT = 1


@dataclass(frozen=True)
class VirtualFileDescriptor:
    name: str
    size: int


class _FORMATETC(ctypes.Structure):
    _fields_ = [("cfFormat", ctypes.c_ushort), ("ptd", ctypes.c_void_p),
                ("dwAspect", ctypes.c_uint32), ("lindex", ctypes.c_long),
                ("tymed", ctypes.c_uint32)]


class _STGMEDIUM(ctypes.Structure):
    _fields_ = [("tymed", ctypes.c_uint32), ("data", ctypes.c_void_p),
                ("pUnkForRelease", ctypes.c_void_p)]


class _FILEDESCRIPTORW(ctypes.Structure):
    _fields_ = [("dwFlags", ctypes.c_uint32), ("clsid", ctypes.c_byte * 16),
                ("sizel", ctypes.c_long * 2), ("pointl", ctypes.c_long * 2),
                ("dwFileAttributes", ctypes.c_uint32), ("ftCreationTime", ctypes.c_uint32 * 2),
                ("ftLastAccessTime", ctypes.c_uint32 * 2), ("ftLastWriteTime", ctypes.c_uint32 * 2),
                ("nFileSizeHigh", ctypes.c_uint32), ("nFileSizeLow", ctypes.c_uint32),
                ("cFileName", ctypes.c_wchar * 260)]


def _register_clipboard_format(name: str) -> int:
    user32 = ctypes.windll.user32
    user32.RegisterClipboardFormatW.argtypes = [ctypes.c_wchar_p]
    user32.RegisterClipboardFormatW.restype = ctypes.c_uint
    return user32.RegisterClipboardFormatW(name)


def _safe_virtual_name(value: str) -> str:
    name = value.replace("\\", "/").split("/")[-1].strip().rstrip(". ")
    if not name or name in {".", ".."}:
        raise OSError("Outlook supplied an invalid attachment name.")
    return name


def parse_file_group_descriptor(data: bytes) -> list[VirtualFileDescriptor]:
    if len(data) < 4:
        raise OSError("The virtual-file descriptor is incomplete.")
    count = struct.unpack_from("<I", data)[0]
    descriptor_size = ctypes.sizeof(_FILEDESCRIPTORW)
    if count > 10000 or len(data) < 4 + count * descriptor_size:
        raise OSError("The virtual-file descriptor has an invalid item count.")
    result = []
    for index in range(count):
        descriptor = _FILEDESCRIPTORW.from_buffer_copy(data, 4 + index * descriptor_size)
        result.append(VirtualFileDescriptor(_safe_virtual_name(descriptor.cFileName),
                                            (descriptor.nFileSizeHigh << 32) | descriptor.nFileSizeLow))
    return result


def _vtable_method(pointer: int, index: int, result_type, *argument_types):
    table = ctypes.cast(pointer, ctypes.POINTER(ctypes.POINTER(ctypes.c_void_p))).contents
    return ctypes.WINFUNCTYPE(result_type, ctypes.c_void_p, *argument_types)(table[index])


def _release_interface(pointer: int) -> None:
    if pointer:
        _vtable_method(pointer, 2, ctypes.c_ulong)(pointer)


def _get_ole_clipboard():
    ole32 = ctypes.windll.ole32
    ole32.OleInitialize.argtypes = [ctypes.c_void_p]; ole32.OleInitialize.restype = ctypes.c_long
    initialized = ole32.OleInitialize(None)
    if initialized < 0:
        raise OSError(f"Cannot initialize OLE clipboard access (0x{initialized & 0xFFFFFFFF:08X}).")
    pointer = ctypes.c_void_p()
    ole32.OleGetClipboard.argtypes = [ctypes.POINTER(ctypes.c_void_p)]
    ole32.OleGetClipboard.restype = ctypes.c_long
    status = ole32.OleGetClipboard(ctypes.byref(pointer))
    if status < 0 or not pointer.value:
        ole32.OleUninitialize()
        raise OSError("The Windows clipboard does not expose an OLE data object.")
    return pointer.value, initialized in (0, 1)


def _get_medium(data_object: int, format_id: int, index: int, tymed: int) -> _STGMEDIUM:
    request = _FORMATETC(format_id, None, DVASPECT_CONTENT, index, tymed)
    medium = _STGMEDIUM()
    get_data = _vtable_method(data_object, 3, ctypes.c_long,
                              ctypes.POINTER(_FORMATETC), ctypes.POINTER(_STGMEDIUM))
    status = get_data(data_object, ctypes.byref(request), ctypes.byref(medium))
    if status < 0:
        raise OSError(f"Outlook could not render attachment data (0x{status & 0xFFFFFFFF:08X}).")
    return medium


def _release_medium(medium: _STGMEDIUM) -> None:
    ctypes.windll.ole32.ReleaseStgMedium(ctypes.byref(medium))


def _global_bytes(handle: int) -> bytes:
    kernel32 = ctypes.windll.kernel32
    kernel32.GlobalLock.argtypes = [ctypes.c_void_p]; kernel32.GlobalLock.restype = ctypes.c_void_p
    kernel32.GlobalSize.argtypes = [ctypes.c_void_p]; kernel32.GlobalSize.restype = ctypes.c_size_t
    kernel32.GlobalUnlock.argtypes = [ctypes.c_void_p]
    pointer, size = kernel32.GlobalLock(handle), kernel32.GlobalSize(handle)
    if not pointer:
        raise OSError("Cannot read virtual-file clipboard memory.")
    try: return ctypes.string_at(pointer, size)
    finally: kernel32.GlobalUnlock(handle)


def _virtual_descriptors_from_object(data_object: int) -> list[VirtualFileDescriptor]:
    format_id = _register_clipboard_format("FileGroupDescriptorW")
    medium = _get_medium(data_object, format_id, -1, TYMED_HGLOBAL)
    try:
        if medium.tymed != TYMED_HGLOBAL or not medium.data:
            raise OSError("Outlook returned an unsupported attachment descriptor medium.")
        return parse_file_group_descriptor(_global_bytes(medium.data))
    finally:
        _release_medium(medium)


def data_object_has_format(data_object: int, format_id: int, index: int = -1,
                           tymed: int = TYMED_HGLOBAL) -> bool:
    """Return whether an OLE IDataObject can render the requested format."""
    request = _FORMATETC(format_id, None, DVASPECT_CONTENT, index, tymed)
    query = _vtable_method(data_object, 5, ctypes.c_long, ctypes.POINTER(_FORMATETC))
    return query(data_object, ctypes.byref(request)) >= 0


def virtual_file_format_id() -> int:
    return _register_clipboard_format("FileGroupDescriptorW")


def get_virtual_file_descriptors() -> list[VirtualFileDescriptor]:
    if os.name != "nt":
        return []
    data_object = None; uninitialize = False
    try:
        data_object, uninitialize = _get_ole_clipboard()
        return _virtual_descriptors_from_object(data_object)
    except OSError:
        return []
    finally:
        if data_object: _release_interface(data_object)
        if uninitialize: ctypes.windll.ole32.OleUninitialize()


def _write_stream(stream_pointer: int, target: Path) -> None:
    seek = _vtable_method(stream_pointer, 5, ctypes.c_long, ctypes.c_longlong,
                          ctypes.c_uint32, ctypes.POINTER(ctypes.c_ulonglong))
    position = ctypes.c_ulonglong()
    seek(stream_pointer, 0, 0, ctypes.byref(position))
    read = _vtable_method(stream_pointer, 3, ctypes.c_long, ctypes.c_void_p,
                          ctypes.c_ulong, ctypes.POINTER(ctypes.c_ulong))
    buffer = ctypes.create_string_buffer(1024 * 1024)
    with target.open("wb") as output:
        while True:
            count = ctypes.c_ulong()
            status = read(stream_pointer, buffer, len(buffer), ctypes.byref(count))
            if status < 0:
                raise OSError(f"Cannot read Outlook attachment stream (0x{status & 0xFFFFFFFF:08X}).")
            if count.value:
                output.write(buffer.raw[:count.value])
            if count.value == 0 or status == 1:
                break


def _write_virtual_medium(medium: _STGMEDIUM, target: Path, expected_size: int) -> None:
    if medium.tymed == TYMED_ISTREAM and medium.data:
        _write_stream(medium.data, target)
    elif medium.tymed == TYMED_HGLOBAL and medium.data:
        data = _global_bytes(medium.data)
        target.write_bytes(data[:expected_size] if expected_size else data)
    elif medium.tymed == TYMED_FILE and medium.data:
        shutil.copy2(ctypes.wstring_at(medium.data), target)
    else:
        raise OSError(f"Unsupported Outlook attachment medium: {medium.tymed}")


def extract_virtual_files_from_data_object(
        data_object: int, destination: Path) -> tuple[list[Path], list[tuple[str, str]]]:
    """Materialize Outlook/Teams virtual files while IDataObject is still valid."""
    extracted, failures = [], []
    destination.mkdir(parents=True, exist_ok=True)
    descriptors = _virtual_descriptors_from_object(data_object)
    content_format = _register_clipboard_format("FileContents")
    for index, descriptor in enumerate(descriptors):
        target = destination / descriptor.name
        if target.exists():
            target = target.with_name(f"{target.stem} ({index + 2}){target.suffix}")
        medium = None
        try:
            medium = _get_medium(data_object, content_format, index,
                                 TYMED_ISTREAM | TYMED_HGLOBAL | TYMED_FILE)
            _write_virtual_medium(medium, target, descriptor.size)
            extracted.append(target)
        except OSError as exc:
            failures.append((descriptor.name, str(exc)))
            try: target.unlink(missing_ok=True)
            except OSError: pass
        finally:
            if medium is not None: _release_medium(medium)
    return extracted, failures


def extract_virtual_files(destination: Path) -> tuple[list[Path], list[tuple[str, str]]]:
    if os.name != "nt":
        return [], []
    data_object = None; uninitialize = False
    try:
        data_object, uninitialize = _get_ole_clipboard()
        return extract_virtual_files_from_data_object(data_object, destination)
    finally:
        if data_object: _release_interface(data_object)
        if uninitialize: ctypes.windll.ole32.OleUninitialize()


def _open_clipboard() -> None:
    user32 = ctypes.windll.user32
    for _ in range(10):
        if user32.OpenClipboard(None):
            return
        time.sleep(0.02)
    raise OSError("The Windows clipboard is busy.")


def _global_data(payload: bytes) -> int:
    kernel32 = ctypes.windll.kernel32
    kernel32.GlobalAlloc.restype = ctypes.c_void_p
    kernel32.GlobalAlloc.argtypes = [ctypes.c_uint, ctypes.c_size_t]
    kernel32.GlobalLock.restype = ctypes.c_void_p
    kernel32.GlobalLock.argtypes = [ctypes.c_void_p]
    kernel32.GlobalUnlock.argtypes = [ctypes.c_void_p]
    kernel32.GlobalFree.argtypes = [ctypes.c_void_p]
    handle = kernel32.GlobalAlloc(GMEM_MOVEABLE_ZEROINIT, len(payload))
    if not handle:
        raise MemoryError("Cannot allocate clipboard memory.")
    pointer = kernel32.GlobalLock(handle)
    if not pointer:
        kernel32.GlobalFree(handle)
        raise MemoryError("Cannot lock clipboard memory.")
    ctypes.memmove(pointer, payload, len(payload))
    kernel32.GlobalUnlock(handle)
    return handle


def set_file_clipboard(paths: list[Path], cut: bool = False) -> None:
    """Publish files in the same clipboard formats used by File Explorer."""
    if os.name != "nt":
        raise OSError("File clipboard integration requires Windows.")
    resolved = [str(path.resolve()) for path in paths]
    if not resolved:
        return
    dropfiles = struct.pack("<IiiII", 20, 0, 0, 0, 1)
    dropfiles += ("\0".join(resolved) + "\0\0").encode("utf-16le")
    drop_handle = _global_data(dropfiles)
    effect_handle = _global_data(struct.pack("<I", DROPEFFECT_MOVE if cut else DROPEFFECT_COPY))
    user32 = ctypes.windll.user32
    user32.SetClipboardData.restype = ctypes.c_void_p
    user32.SetClipboardData.argtypes = [ctypes.c_uint, ctypes.c_void_p]
    effect_format = _register_clipboard_format("Preferred DropEffect")
    _open_clipboard()
    try:
        if not user32.EmptyClipboard():
            raise OSError("Cannot clear the Windows clipboard.")
        if not user32.SetClipboardData(CF_HDROP, drop_handle):
            raise OSError("Cannot place files on the Windows clipboard.")
        drop_handle = None  # Windows owns successful clipboard handles.
        if not user32.SetClipboardData(effect_format, effect_handle):
            raise OSError("Cannot set the clipboard copy/cut mode.")
        effect_handle = None
    finally:
        user32.CloseClipboard()
        if drop_handle:
            ctypes.windll.kernel32.GlobalFree(drop_handle)
        if effect_handle:
            ctypes.windll.kernel32.GlobalFree(effect_handle)


def get_file_clipboard() -> tuple[list[Path], bool]:
    """Read files copied or cut by PFC or Windows File Explorer."""
    if os.name != "nt":
        return [], False
    user32, shell32, kernel32 = ctypes.windll.user32, ctypes.windll.shell32, ctypes.windll.kernel32
    user32.GetClipboardData.restype = ctypes.c_void_p
    user32.GetClipboardData.argtypes = [ctypes.c_uint]
    kernel32.GlobalLock.restype = ctypes.c_void_p
    kernel32.GlobalLock.argtypes = [ctypes.c_void_p]
    kernel32.GlobalUnlock.argtypes = [ctypes.c_void_p]
    shell32.DragQueryFileW.argtypes = [ctypes.c_void_p, ctypes.c_uint, ctypes.c_wchar_p, ctypes.c_uint]
    effect_format = _register_clipboard_format("Preferred DropEffect")
    _open_clipboard()
    try:
        drop_handle = user32.GetClipboardData(CF_HDROP)
        if not drop_handle:
            return [], False
        count = shell32.DragQueryFileW(drop_handle, 0xFFFFFFFF, None, 0)
        paths = []
        for index in range(count):
            length = shell32.DragQueryFileW(drop_handle, index, None, 0)
            buffer = ctypes.create_unicode_buffer(length + 1)
            shell32.DragQueryFileW(drop_handle, index, buffer, length + 1)
            paths.append(Path(buffer.value))
        cut = False
        effect_handle = user32.GetClipboardData(effect_format)
        if effect_handle:
            pointer = kernel32.GlobalLock(effect_handle)
            if pointer:
                cut = ctypes.c_uint32.from_address(pointer).value == DROPEFFECT_MOVE
                kernel32.GlobalUnlock(effect_handle)
        return paths, cut
    finally:
        user32.CloseClipboard()


def clear_file_clipboard() -> None:
    if os.name != "nt":
        return
    _open_clipboard()
    try:
        ctypes.windll.user32.EmptyClipboard()
    finally:
        ctypes.windll.user32.CloseClipboard()


import base64
import binascii
import ctypes
import os
import struct
import zlib
from pathlib import Path
from tkinter import PhotoImage


class _SHFILEINFO(ctypes.Structure):
    _fields_ = [("hIcon", ctypes.c_void_p), ("iIcon", ctypes.c_int),
                ("dwAttributes", ctypes.c_uint32), ("szDisplayName", ctypes.c_wchar * 260),
                ("szTypeName", ctypes.c_wchar * 80)]


class _BITMAPINFOHEADER(ctypes.Structure):
    _fields_ = [("biSize", ctypes.c_uint32), ("biWidth", ctypes.c_long),
                ("biHeight", ctypes.c_long), ("biPlanes", ctypes.c_ushort),
                ("biBitCount", ctypes.c_ushort), ("biCompression", ctypes.c_uint32),
                ("biSizeImage", ctypes.c_uint32), ("biXPelsPerMeter", ctypes.c_long),
                ("biYPelsPerMeter", ctypes.c_long), ("biClrUsed", ctypes.c_uint32),
                ("biClrImportant", ctypes.c_uint32)]


class _BITMAPINFO(ctypes.Structure):
    _fields_ = [("bmiHeader", _BITMAPINFOHEADER), ("bmiColors", ctypes.c_uint32 * 3)]


def _chunk(kind: bytes, data: bytes) -> bytes:
    return struct.pack(">I", len(data)) + kind + data + struct.pack(">I", binascii.crc32(kind + data) & 0xFFFFFFFF)


def _png_from_bgra(raw: bytes, size: int) -> bytes:
    rgba = bytearray()
    has_alpha = any(raw[index + 3] for index in range(0, len(raw), 4))
    for row in range(size):
        rgba.append(0)
        for column in range(size):
            index = (row * size + column) * 4
            blue, green, red, alpha = raw[index:index + 4]
            if not has_alpha:
                alpha = 255 if red or green or blue else 0
            rgba.extend((red, green, blue, alpha))
    header = struct.pack(">IIBBBBB", size, size, 8, 6, 0, 0, 0)
    return b"\x89PNG\r\n\x1a\n" + _chunk(b"IHDR", header) + _chunk(b"IDAT", zlib.compress(bytes(rgba), 9)) + _chunk(b"IEND", b"")


def _inside_polygon(x: float, y: float, points) -> bool:
    inside = False
    previous = points[-1]
    for current in points:
        x1, y1 = previous; x2, y2 = current
        if (y1 > y) != (y2 > y):
            crossing = (x2 - x1) * (y - y1) / (y2 - y1) + x1
            if x < crossing:
                inside = not inside
        previous = current
    return inside


def _paint_polygon(pixels: bytearray, canvas_size: int, points, color) -> None:
    left = max(0, int(min(x for x, _y in points)))
    right = min(canvas_size - 1, int(max(x for x, _y in points)) + 1)
    top = max(0, int(min(y for _x, y in points)))
    bottom = min(canvas_size - 1, int(max(y for _x, y in points)) + 1)
    for row in range(top, bottom + 1):
        for column in range(left, right + 1):
            if _inside_polygon(column + 0.5, row + 0.5, points):
                index = (row * canvas_size + column) * 4
                pixels[index:index + 4] = bytes(color)


def pfc_icon_png(size: int = 32) -> bytes:
    """Render the embedded four-panel transfer mark as an antialiased PNG."""
    if size < 8:
        raise ValueError("PFC icon size must be at least 8 pixels")
    supersample = 4
    canvas_size = size * supersample
    factor = canvas_size / 64
    pixels = bytearray(canvas_size * canvas_size * 4)
    arrow = ((4.2, 9.8), (16.2, 21.8), (12.6, 25.4),
             (29.0, 29.0), (25.4, 12.6), (21.8, 16.2), (9.8, 4.2))
    inner_arrow = ((5.4, 8.6), (17.4, 20.6), (14.2, 23.8),
                   (28.1, 28.1), (23.8, 14.2), (20.6, 17.4), (8.6, 5.4))
    outline, fill = (32, 67, 92, 255), (247, 177, 52, 255)

    def rotate(points):
        return tuple((64 - y, x) for x, y in points)

    current, current_inner = arrow, inner_arrow
    for _index in range(4):
        scaled = tuple((x * factor, y * factor) for x, y in current)
        _paint_polygon(pixels, canvas_size, scaled, outline)
        inset = tuple((x * factor, y * factor) for x, y in current_inner)
        _paint_polygon(pixels, canvas_size, inset, fill)
        current = rotate(current)
        current_inner = rotate(current_inner)

    rgba = bytearray()
    for row in range(size):
        rgba.append(0)
        for column in range(size):
            samples = []
            for sub_y in range(supersample):
                for sub_x in range(supersample):
                    index = (((row * supersample + sub_y) * canvas_size +
                              column * supersample + sub_x) * 4)
                    samples.append(pixels[index:index + 4])
            alpha_sum = sum(sample[3] for sample in samples)
            alpha = round(alpha_sum / len(samples))
            if alpha_sum:
                red = round(sum(sample[0] * sample[3] for sample in samples) / alpha_sum)
                green = round(sum(sample[1] * sample[3] for sample in samples) / alpha_sum)
                blue = round(sum(sample[2] * sample[3] for sample in samples) / alpha_sum)
            else:
                red = green = blue = 0
            rgba.extend((red, green, blue, alpha))
    header = struct.pack(">IIBBBBB", size, size, 8, 6, 0, 0, 0)
    return (b"\x89PNG\r\n\x1a\n" + _chunk(b"IHDR", header) +
            _chunk(b"IDAT", zlib.compress(bytes(rgba), 9)) + _chunk(b"IEND", b""))


def create_pfc_icon(size: int = 32) -> PhotoImage:
    encoded = base64.b64encode(pfc_icon_png(size)).decode("ascii")
    return PhotoImage(data=encoded, format="png")


class ShellIconProvider:
    """Caches native Windows Shell icons as Tk images."""

    def __init__(self, size: int = 16, text_gap: int | None = None) -> None:
        self.size = size
        self.text_gap = max(4, round(size * 0.3)) if text_gap is None else text_gap
        self.cache: dict[str, PhotoImage] = {}
        self.blank = PhotoImage(width=size + self.text_gap, height=size)

    def get(self, path: Path, is_dir: bool) -> PhotoImage:
        if os.name != "nt":
            return self.blank
        suffix = path.suffix.casefold()
        key = "<folder>" if is_dir else (str(path) if suffix in {".exe", ".lnk", ".ico"} else suffix or "<file>")
        if key not in self.cache:
            icon = self._load(path)
            self.cache[key] = self._with_text_gap(icon) if icon is not None else self.blank
        return self.cache[key]

    def _with_text_gap(self, icon: PhotoImage) -> PhotoImage:
        padded = PhotoImage(width=self.size + self.text_gap, height=self.size)
        padded.tk.call(str(padded), "copy", str(icon), "-to", 0, 0)
        return padded

    def _load(self, path: Path) -> PhotoImage | None:
        shell32, user32, gdi32 = ctypes.windll.shell32, ctypes.windll.user32, ctypes.windll.gdi32
        shell32.SHGetFileInfoW.restype = ctypes.c_size_t
        shell32.SHGetFileInfoW.argtypes = [ctypes.c_wchar_p, ctypes.c_uint32, ctypes.POINTER(_SHFILEINFO), ctypes.c_uint, ctypes.c_uint]
        user32.GetDC.restype = ctypes.c_void_p
        user32.GetDC.argtypes = [ctypes.c_void_p]
        user32.ReleaseDC.argtypes = [ctypes.c_void_p, ctypes.c_void_p]
        user32.DestroyIcon.argtypes = [ctypes.c_void_p]
        user32.DrawIconEx.argtypes = [ctypes.c_void_p, ctypes.c_int, ctypes.c_int, ctypes.c_void_p,
                                      ctypes.c_int, ctypes.c_int, ctypes.c_uint, ctypes.c_void_p, ctypes.c_uint]
        gdi32.CreateCompatibleDC.restype = ctypes.c_void_p
        gdi32.CreateCompatibleDC.argtypes = [ctypes.c_void_p]
        gdi32.CreateDIBSection.restype = ctypes.c_void_p
        gdi32.CreateDIBSection.argtypes = [ctypes.c_void_p, ctypes.POINTER(_BITMAPINFO), ctypes.c_uint,
                                           ctypes.POINTER(ctypes.c_void_p), ctypes.c_void_p, ctypes.c_uint]
        gdi32.SelectObject.restype = ctypes.c_void_p
        gdi32.SelectObject.argtypes = [ctypes.c_void_p, ctypes.c_void_p]
        gdi32.DeleteObject.argtypes = [ctypes.c_void_p]
        gdi32.DeleteDC.argtypes = [ctypes.c_void_p]
        info = _SHFILEINFO()
        # The small Shell handle reliably contains alpha on all supported Windows
        # versions. DrawIconEx scales it to the selected UI profile; some large
        # handles render fully transparent when converted through a 32-bit DIB.
        flags = 0x1 | 0x100
        if not shell32.SHGetFileInfoW(str(path), 0, ctypes.byref(info), ctypes.sizeof(info), flags):
            return None
        screen = user32.GetDC(None)
        memory = gdi32.CreateCompatibleDC(screen)
        bitmap_info = _BITMAPINFO()
        bitmap_info.bmiHeader.biSize = ctypes.sizeof(_BITMAPINFOHEADER)
        bitmap_info.bmiHeader.biWidth = self.size
        bitmap_info.bmiHeader.biHeight = -self.size
        bitmap_info.bmiHeader.biPlanes = 1
        bitmap_info.bmiHeader.biBitCount = 32
        bitmap_info.bmiHeader.biCompression = 0
        bits = ctypes.c_void_p()
        bitmap = gdi32.CreateDIBSection(memory, ctypes.byref(bitmap_info), 0, ctypes.byref(bits), None, 0)
        old = gdi32.SelectObject(memory, bitmap)
        ctypes.memset(bits.value, 0, self.size * self.size * 4)
        user32.DrawIconEx(memory, 0, 0, info.hIcon, self.size, self.size, 0, None, 0x3)
        raw = ctypes.string_at(bits.value, self.size * self.size * 4)
        gdi32.SelectObject(memory, old)
        gdi32.DeleteObject(bitmap)
        gdi32.DeleteDC(memory)
        user32.ReleaseDC(None, screen)
        user32.DestroyIcon(info.hIcon)
        try:
            encoded = base64.b64encode(_png_from_bgra(raw, self.size)).decode("ascii")
            return PhotoImage(data=encoded, format="png")
        except Exception:
            return None


import tkinter as tk
import tkinter.font as tkfont
from tkinter import ttk


TAB_COLORS = {
    "default": ("Default", "#c7d3dd"),
    "amber": ("Amber", "#f2c14e"),
    "coral": ("Coral", "#f58b68"),
    "pink": ("Pink", "#e96ba8"),
    "violet": ("Violet", "#8d7be5"),
    "teal": ("Teal", "#55b9ae"),
}

TAB_STYLES = {
    "right_skirt": "Right Skirt",
    "rounded": "Rounded",
    "squarish": "Squarish",
}


def add_scaled_cascade(menu: tk.Menu, label: str, submenu: tk.Menu) -> None:
    """Keep a native menu model; PFC draws header cascades itself."""
    menu.add_cascade(label=label, menu=submenu)


def align_scaled_cascade_arrows(menu: tk.Menu) -> None:
    """Compatibility no-op for the native menu model."""


def _refresh_scaled_indicators(menu: tk.Menu) -> None:
    for index, variable, value in getattr(menu, "_pfc_scaled_indicators", ()):
        selected = bool(variable.get()) if value is None else variable.get() == value
        menu.entryconfigure(index, accelerator="✓" if selected else "")


def _register_scaled_indicator(menu: tk.Menu, variable, value) -> None:
    if not hasattr(menu, "_pfc_scaled_indicators"):
        menu._pfc_scaled_indicators = []
        menu.configure(postcommand=lambda target=menu: _refresh_scaled_indicators(target))
    menu._pfc_scaled_indicators.append((menu.index("end"), variable, value))
    _refresh_scaled_indicators(menu)


def add_scaled_checkbutton(menu: tk.Menu, label: str, variable, command=None) -> None:
    menu.add_checkbutton(label=label, variable=variable, command=command, indicatoron=False)
    _register_scaled_indicator(menu, variable, None)


def add_scaled_radiobutton(menu: tk.Menu, label: str, value, variable, command=None) -> None:
    menu.add_radiobutton(label=label, value=value, variable=variable, command=command,
                         indicatoron=False)
    _register_scaled_indicator(menu, variable, value)


class HeaderPopupController:
    """Draw scalable, keyboard-accessible header menus without native glyphs."""

    def __init__(self, owner, descriptions=None):
        self.owner = owner
        self.descriptions = descriptions or {}
        self.popups = []
        self.tooltip = None
        self.tooltip_job = None

    def show(self, button, menu) -> None:
        self.close_all()
        popup = _HeaderPopup(self, menu, None)
        self.popups = [popup]
        popup.show(button.winfo_rootx(), button.winfo_rooty() + button.winfo_height())
        popup.top.grab_set_global()
        popup.canvas.focus_force()

    def open_child(self, parent, index) -> None:
        depth = self.popups.index(parent)
        self._close_from(depth + 1)
        submenu_name = parent.menu.entrycget(index, "menu")
        if not submenu_name:
            return
        submenu = parent.menu.nametowidget(submenu_name)
        child = _HeaderPopup(self, submenu, parent)
        self.popups.append(child)
        row_top = parent.row_bounds[index][0]
        x = parent.top.winfo_rootx() + parent.width - 1
        y = parent.top.winfo_rooty() + row_top
        if x + child.width > child.top.winfo_screenwidth():
            x = parent.top.winfo_rootx() - child.width + 1
        child.show(x, y)
        child.canvas.focus_force()

    def close_child(self, popup) -> None:
        depth = self.popups.index(popup)
        parent = popup.parent
        self._close_from(depth)
        if parent is not None:
            parent.canvas.focus_force()

    def close_all(self) -> None:
        self._hide_tooltip()
        if self.popups:
            try:
                self.popups[0].top.grab_release()
            except tk.TclError:
                pass
        self._close_from(0)

    def _close_from(self, depth: int) -> None:
        self._hide_tooltip()
        for popup in reversed(self.popups[depth:]):
            try:
                popup.top.destroy()
            except tk.TclError:
                pass
        del self.popups[depth:]

    def pointer_inside(self, x: int, y: int) -> bool:
        return any(p.top.winfo_exists() and p.top.winfo_rootx() <= x < p.top.winfo_rootx() + p.width
                   and p.top.winfo_rooty() <= y < p.top.winfo_rooty() + p.height
                   for p in self.popups)

    def schedule_tooltip(self, popup, index) -> None:
        self._hide_tooltip()
        self.tooltip_job = self.owner.after(5000, lambda: self._show_tooltip(popup, index))

    def _show_tooltip(self, popup, index) -> None:
        self.tooltip_job = None
        if popup not in self.popups:
            return
        label = popup.menu.entrycget(index, "label")
        text = self.descriptions.get(label, label)
        tip = tk.Toplevel(self.owner)
        tip.overrideredirect(True)
        tip.attributes("-topmost", True)
        x, y = self.owner.winfo_pointerxy()
        tip.geometry(f"+{x + 14}+{y + 18}")
        tk.Label(tip, text=text, justify="left", background="#fffbd6", foreground="#18232c",
                 relief="solid", borderwidth=1, padx=7, pady=4,
                 font=tkfont.nametofont("TkDefaultFont")).pack()
        self.tooltip = tip

    def _hide_tooltip(self) -> None:
        if self.tooltip_job is not None:
            try:
                self.owner.after_cancel(self.tooltip_job)
            except tk.TclError:
                pass
            self.tooltip_job = None
        if self.tooltip is not None:
            try:
                self.tooltip.destroy()
            except tk.TclError:
                pass
            self.tooltip = None


class _HeaderPopup:
    BG, FG, DISABLED, ACTIVE_BG, ACTIVE_FG, BORDER = (
        "#f0f0f0", "#101010", "#808080", "#087bdc", "#ffffff", "#8a8a8a")

    def __init__(self, controller, menu, parent):
        self.controller, self.menu, self.parent = controller, menu, parent
        self.top = tk.Toplevel(parent.top if parent is not None else controller.owner)
        self.top.withdraw()
        self.top.overrideredirect(True)
        self.top.attributes("-topmost", True)
        self.font = tkfont.nametofont("TkMenuFont")
        self.selected = None
        self.items = []
        self.row_bounds = {}
        self._run_postcommand()
        self._measure()
        self.canvas = tk.Canvas(self.top, width=self.width, height=self.height, background=self.BG,
                                highlightthickness=1, highlightbackground=self.BORDER, takefocus=True)
        self.canvas.pack()
        self.canvas.bind("<Motion>", self._motion)
        self.canvas.bind("<Leave>", lambda _event: self.controller._hide_tooltip())
        self.canvas.bind("<ButtonRelease-1>", self._click)
        self.canvas.bind("<ButtonPress-1>", self._outside_click)
        self.top.bind("<ButtonPress-1>", self._outside_click, add="+")
        self.canvas.bind("<Down>", lambda _event: self._move(1))
        self.canvas.bind("<Up>", lambda _event: self._move(-1))
        self.canvas.bind("<Right>", lambda _event: self._open_selected())
        self.canvas.bind("<Left>", lambda _event: self._left())
        self.canvas.bind("<Return>", lambda _event: self._invoke_selected())
        self.canvas.bind("<space>", lambda _event: self._invoke_selected())
        self.canvas.bind("<Escape>", lambda _event: self._escape())
        self._draw()

    def _run_postcommand(self) -> None:
        command = self.menu.cget("postcommand")
        if command:
            try:
                self.menu.tk.eval(command)
            except tk.TclError:
                pass

    def _measure(self) -> None:
        end = self.menu.index("end")
        label_width = accelerator_width = 0
        line = self.font.metrics("linespace")
        self.row_height = max(24, line + max(8, line // 3))
        y = 3
        for index in range(end + 1 if end is not None else 0):
            kind = self.menu.type(index)
            if kind == "tearoff":
                continue
            if kind == "separator":
                height = max(7, line // 3)
                self.items.append((index, kind, "", "", "normal"))
            else:
                label = self.menu.entrycget(index, "label")
                accelerator = self.menu.entrycget(index, "accelerator")
                state = self.menu.entrycget(index, "state")
                label_width = max(label_width, self.font.measure(label))
                if accelerator != "✓":
                    accelerator_width = max(accelerator_width, self.font.measure(accelerator))
                height = self.row_height
                self.items.append((index, kind, label, accelerator, state))
            self.row_bounds[index] = (y, y + height)
            y += height
        marker = max(line, self.font.measure("▶"), self.font.measure("✓"))
        self.left_pad = max(10, line // 2)
        self.label_x = self.left_pad
        self.marker_width = marker + self.left_pad
        gap = max(18, line)
        self.width = self.left_pad + label_width + gap + accelerator_width + self.marker_width
        self.height = y + 3
        self.accelerator_x = self.width - self.marker_width - self.left_pad
        self.marker_x = self.width - self.left_pad

    def show(self, x: int, y: int) -> None:
        screen_w, screen_h = self.top.winfo_screenwidth(), self.top.winfo_screenheight()
        x = max(0, min(x, screen_w - self.width))
        y = max(0, min(y, screen_h - self.height))
        self.top.geometry(f"{self.width}x{self.height}+{x}+{y}")
        self.top.deiconify()
        self.top.lift()

    def _draw(self) -> None:
        self.canvas.delete("all")
        for index, kind, label, accelerator, state in self.items:
            top, bottom = self.row_bounds[index]
            if kind == "separator":
                y = (top + bottom) // 2
                self.canvas.create_line(self.left_pad, y, self.width - self.left_pad, y,
                                        fill="#b8b8b8")
                continue
            active = index == self.selected and state != "disabled"
            bg = self.ACTIVE_BG if active else self.BG
            fg = self.ACTIVE_FG if active else (self.DISABLED if state == "disabled" else self.FG)
            self.canvas.create_rectangle(1, top, self.width - 1, bottom, fill=bg, outline="")
            self.canvas.create_text(self.label_x, (top + bottom) // 2, text=label, anchor="w",
                                    fill=fg, font=self.font)
            if accelerator and accelerator != "✓":
                self.canvas.create_text(self.accelerator_x, (top + bottom) // 2, text=accelerator,
                                        anchor="e", fill=fg, font=self.font)
            marker = "▶" if kind == "cascade" else ("✓" if accelerator == "✓" else "")
            if marker:
                self.canvas.create_text(self.marker_x, (top + bottom) // 2, text=marker,
                                        anchor="e", fill=fg, font=self.font)

    def _index_at(self, y):
        for index, (top, bottom) in self.row_bounds.items():
            if top <= y < bottom and self.menu.type(index) != "separator":
                return index
        return None

    def _select(self, index) -> None:
        if index == self.selected:
            return
        self.selected = index
        self._draw()
        if index is not None:
            self.controller.schedule_tooltip(self, index)
            if self.menu.type(index) == "cascade" and self.menu.entrycget(index, "state") != "disabled":
                self.controller.open_child(self, index)
            else:
                self.controller._close_from(self.controller.popups.index(self) + 1)

    def _motion(self, event) -> None:
        self._select(self._index_at(event.y))

    def _outside_click(self, event) -> str | None:
        if not self.controller.pointer_inside(event.x_root, event.y_root):
            self.controller.close_all()
            return "break"
        return None

    def _click(self, event) -> str:
        index = self._index_at(event.y)
        if index is not None:
            self._select(index)
            self._invoke(index)
        return "break"

    def _enabled_indexes(self):
        return [index for index, kind, _label, _accelerator, state in self.items
                if kind != "separator" and state != "disabled"]

    def _move(self, direction: int) -> str:
        indexes = self._enabled_indexes()
        if not indexes:
            return "break"
        if self.selected not in indexes:
            target = indexes[0 if direction > 0 else -1]
        else:
            target = indexes[(indexes.index(self.selected) + direction) % len(indexes)]
        self._select(target)
        return "break"

    def _open_selected(self) -> str:
        if self.selected is not None and self.menu.type(self.selected) == "cascade":
            self.controller.open_child(self, self.selected)
            self.controller.popups[-1]._move(1)
        return "break"

    def _invoke_selected(self) -> str:
        if self.selected is not None:
            self._invoke(self.selected)
        return "break"

    def _invoke(self, index) -> None:
        if self.menu.entrycget(index, "state") == "disabled":
            return
        if self.menu.type(index) == "cascade":
            self.controller.open_child(self, index)
            self.controller.popups[-1].canvas.focus_force()
            return
        menu, controller = self.menu, self.controller
        controller.close_all()
        menu.invoke(index)

    def _left(self) -> str:
        if self.parent is not None:
            self.controller.close_child(self)
        return "break"

    def _escape(self) -> str:
        if self.parent is not None:
            self.controller.close_child(self)
        else:
            self.controller.close_all()
        return "break"


class ChamferNotebook(ttk.Frame):
    """A small Notebook-compatible container with canvas-drawn colored tabs."""

    def __init__(self, master, on_color_changed=None, on_lock_changed=None,
                 on_tabs_reordered=None, on_tab_drag=None,
                 tab_style="right_skirt", **kwargs):
        super().__init__(master, **kwargs)
        self.on_color_changed = on_color_changed or (lambda _child, _color: None)
        self.on_lock_changed = on_lock_changed or (lambda _child, _mode: None)
        self.on_tabs_reordered = on_tabs_reordered or (lambda: None)
        self.on_tab_drag = on_tab_drag or (lambda _action, _tabs, _child, _event: False)
        self._tabs = []
        self._texts = {}
        self._colors = {}
        self._locks = {}
        self._selected = None
        if tab_style == "compact":
            tab_style = "right_skirt"
        self._tab_style = tab_style if tab_style in TAB_STYLES else "right_skirt"
        self._hitboxes = []
        self._drag_tab = None
        self._drag_start_x = 0
        self._drag_original_order = ()
        self._drag_moved = False
        self._drag_external = False
        self._drop_position = None
        self.bar = tk.Canvas(self, height=34, highlightthickness=0, background="#9eafbd")
        self.bar.pack(fill="x", side="top")
        self.bar.bind("<ButtonPress-1>", self._tab_press)
        self.bar.bind("<B1-Motion>", self._tab_motion)
        self.bar.bind("<ButtonRelease-1>", self._tab_release)
        self.bar.bind("<Button-3>", self._popup)
        self.bar.bind("<Configure>", lambda _e: self._draw())

    def add(self, child, text="", color="default", lock="unlocked", position=None, **_kwargs):
        if child not in self._tabs:
            if position is None:
                self._tabs.append(child)
            else:
                self._tabs.insert(max(0, min(position, len(self._tabs))), child)
        self._texts[child] = text
        self._colors[child] = color if color in TAB_COLORS else "default"
        self._locks[child] = lock if lock in {"unlocked", "locked", "reset"} else "unlocked"
        self.select(child)

    def tabs(self):
        return tuple(str(child) for child in self._tabs)

    def select(self, tab=None):
        if tab is None:
            return str(self._selected) if self._selected is not None else ""
        child = self._resolve(tab)
        if child is self._selected:
            return str(child)
        if self._selected is not None:
            self._selected.pack_forget()
        self._selected = child
        child.pack(fill="both", expand=True, side="top")
        self._draw()
        self.event_generate("<<NotebookTabChanged>>")
        return str(child)

    def forget(self, tab):
        child = self._resolve(tab)
        was_selected = child is self._selected
        child.pack_forget()
        self._tabs.remove(child)
        self._texts.pop(child, None); self._colors.pop(child, None); self._locks.pop(child, None)
        if was_selected:
            self._selected = None
            if self._tabs:
                self.select(self._tabs[min(len(self._tabs) - 1, 0)])
        self._draw()

    def tab(self, tab, **options):
        child = self._resolve(tab)
        if "text" in options:
            self._texts[child] = options["text"]; self._draw()
        return {"text": self._texts.get(child, "")}

    def index(self, tab):
        return self._tabs.index(self._resolve(tab))

    def reorder(self, tab, position, notify=True):
        child = self._resolve(tab)
        old_position = self._tabs.index(child)
        new_position = max(0, min(int(position), len(self._tabs) - 1))
        if old_position == new_position:
            return False
        self._tabs.pop(old_position)
        self._tabs.insert(new_position, child)
        self._draw()
        if notify:
            self.on_tabs_reordered()
            self.event_generate("<<NotebookTabsReordered>>")
        return True

    def insertion_index_at(self, x_root, y_root):
        """Return a tab insertion index when a screen point is over this tab bar."""
        if not self.bar.winfo_viewable():
            return None
        left, top = self.bar.winfo_rootx(), self.bar.winfo_rooty()
        if not (left <= x_root < left + self.bar.winfo_width() and
                top <= y_root < top + self.bar.winfo_height()):
            return None
        x = x_root - left
        insertion = 0
        for tab_left, tab_right, _child in self._hitboxes:
            if x > (tab_left + tab_right) / 2:
                insertion += 1
        return insertion

    def _event_root(self, event):
        return (getattr(event, "x_root", self.bar.winfo_rootx() + event.x),
                getattr(event, "y_root", self.bar.winfo_rooty() +
                        getattr(event, "y", max(1, self.bar.winfo_height() // 2))))

    def set_drop_position(self, position=None):
        self._drop_position = position
        self._draw()

    def set_color(self, tab, color, notify=True):
        child = self._resolve(tab)
        self._colors[child] = color if color in TAB_COLORS else "default"
        self._draw()
        if notify:
            self.on_color_changed(child, self._colors[child])

    def set_lock(self, tab, mode, notify=True):
        child = self._resolve(tab)
        self._locks[child] = mode if mode in {"unlocked", "locked", "reset"} else "unlocked"
        self._draw()
        if notify:
            self.on_lock_changed(child, self._locks[child])

    def redraw(self):
        self._draw()

    def set_style(self, style):
        if style == "compact":
            style = "right_skirt"
        self._tab_style = style if style in TAB_STYLES else "right_skirt"
        self._draw()

    def _resolve(self, tab):
        if tab in self._tabs:
            return tab
        return self.nametowidget(tab)

    def _draw(self):
        self.bar.delete("all"); self._hitboxes.clear()
        font = tkfont.nametofont("TkDefaultFont")
        if not hasattr(self, "_active_tab_font"):
            self._active_tab_font = tkfont.Font(root=self, font=font)
        else:
            self._active_tab_font.configure(**font.actual())
        self._active_tab_font.configure(weight="bold")
        right_skirt = self._tab_style == "right_skirt"
        height = max(30, font.metrics("linespace") + 13)
        self.bar.configure(height=height)
        overlap = {"right_skirt": -2, "rounded": 2, "squarish": 0}[self._tab_style]
        x = 3
        drawings = []
        for child in self._tabs:
            text = self._texts.get(child, "")
            lock = self._locks.get(child, "unlocked")
            selected = child is self._selected
            padding = 20 if right_skirt else 28
            width = max(52 if right_skirt else 58, font.measure(text) + padding + (10 if selected else 0))
            color = TAB_COLORS[self._colors.get(child, "default")][1]
            top = 0 if selected else max(4, round(height * 0.22))
            bottom = height if selected else height - 3
            corner = max(6, round(height * 0.28))
            if self._tab_style == "rounded":
                half_corner = round(corner * 0.45)
                points = (x, bottom,
                          x, top + corner,
                          x + 1, top + half_corner,
                          x + half_corner, top + 1,
                          x + corner, top,
                          x + width - corner, top,
                          x + width - half_corner, top + 1,
                          x + width - 1, top + half_corner,
                          x + width, top + corner,
                          x + width, bottom)
                smooth, inset = False, corner
            elif self._tab_style == "right_skirt":
                tail = max(9, round(height * 0.32))
                skirt_height = max(12, round(height * 0.42))
                points = (x, bottom, x, top,
                          x + width - 5, top, x + width, top + 5,
                          x + width, bottom - skirt_height,
                          x + width + 1, bottom - 8,
                          x + width + 4, bottom - 4,
                          x + width + tail, bottom)
                smooth, inset = False, 5
            else:
                points = (x, bottom, x, top, x + width, top, x + width, bottom)
                smooth, inset = False, 4
            drawings.append((selected, points, color, text, x, width, top, child, lock, inset, smooth))
            self._hitboxes.append((x, x + width, child))
            x += width - overlap
        # Paint the selected polygon last so its edges sit in front of
        # both neighbours instead of being covered by the tab to its right.
        for selected, points, color, text, left, width, top, child, lock, tab_inset, smooth in sorted(
                drawings, key=lambda item: item[0]):
            self.bar.create_polygon(points, fill=color, outline="#3b5265" if selected else "#718596",
                                    width=3 if selected else 1, smooth=smooth, splinesteps=18)
            if lock != "unlocked":
                self.bar.create_line(left + tab_inset + 2, top + 2,
                                     left + width - tab_inset - 2, top + 2,
                                     fill="#3b5265", width=3,
                                     dash=() if lock == "locked" else (5, 3))
            if selected:
                self.bar.create_line(left + 2, height - 2, left + width - 2, height - 2,
                                     fill=color, width=4)
            draw_font = self._active_tab_font if selected else font
            self.bar.create_text(left + width / 2, (top + height) / 2 + 1, text=text, font=draw_font,
                                 fill="#10202c")
        if self._drop_position is not None:
            if not self._hitboxes or self._drop_position <= 0:
                marker_x = self._hitboxes[0][0] if self._hitboxes else 3
            elif self._drop_position >= len(self._hitboxes):
                marker_x = self._hitboxes[-1][1]
            else:
                marker_x = self._hitboxes[self._drop_position][0]
            self.bar.create_line(marker_x, 2, marker_x, height - 2,
                                 fill="#0067c0", width=max(3, round(height * 0.11)))
        self.bar.configure(scrollregion=(0, 0, max(x + overlap, self.bar.winfo_width()), height))

    def _at(self, x):
        if self._selected is not None:
            for left, right, child in self._hitboxes:
                if child is self._selected and left <= x <= right:
                    return child
        for left, right, child in reversed(self._hitboxes):
            if left <= x <= right:
                return child
        return None

    def _tab_press(self, event):
        child = self._at(event.x)
        if child is not None:
            self.select(child)
            self._drag_tab = child
            self._drag_start_x = event.x
            self._drag_original_order = tuple(self._tabs)
            self._drag_moved = False
            self._drag_external = False

    def _tab_motion(self, event):
        child = self._drag_tab
        if child is None:
            return
        if not self._drag_moved and abs(event.x - self._drag_start_x) < 5:
            return
        self._drag_moved = True
        x_root, y_root = self._event_root(event)
        synthetic_local = not hasattr(event, "x_root") or not hasattr(event, "y_root")
        own_bar = synthetic_local or self.insertion_index_at(x_root, y_root) is not None
        if not own_bar:
            self._drag_external = True
            accepted = self.on_tab_drag("motion", self, child, event)
            self.bar.configure(cursor="hand2" if accepted else "fleur")
            return
        if self._drag_external:
            self.on_tab_drag("cancel", self, child, event)
            self._tabs[:] = [tab for tab in self._drag_original_order if tab in self._tabs]
            self._draw()
            self._drag_external = False
        self.bar.configure(cursor="fleur")
        insertion = 0
        for left, right, _candidate in self._hitboxes:
            if event.x > (left + right) / 2:
                insertion += 1
        current = self._tabs.index(child)
        if insertion > current:
            insertion -= 1
        self.reorder(child, insertion, notify=False)

    def _tab_release(self, event):
        if self._drag_tab is None:
            return
        child = self._drag_tab
        x_root, y_root = self._event_root(event)
        synthetic_local = not hasattr(event, "x_root") or not hasattr(event, "y_root")
        external = self._drag_external or (not synthetic_local and
                                            self.insertion_index_at(x_root, y_root) is None)
        if external:
            self._tabs[:] = [tab for tab in self._drag_original_order if tab in self._tabs]
            self._draw()
            self.on_tab_drag("drop", self, child, event)
        changed = self._drag_moved and tuple(self._tabs) != self._drag_original_order
        self._drag_tab = None
        self._drag_original_order = ()
        self._drag_moved = False
        self._drag_external = False
        self.bar.configure(cursor="")
        if changed and not external:
            self.on_tabs_reordered()
            self.event_generate("<<NotebookTabsReordered>>")

    def _popup(self, event):
        child = self._at(event.x)
        if child is None:
            return
        self.select(child)
        menu = tk.Menu(self, tearoff=False, font=tkfont.nametofont("TkMenuFont"))
        for key, (label, _color) in TAB_COLORS.items():
            menu.add_command(label=tr(label), command=lambda value=key: self.set_color(child, value))
        menu.add_separator()
        lock_mode = tk.StringVar(value=self._locks.get(child, "unlocked"))
        for label, value in (("Unlocked", "unlocked"),
                             ("Lock (open folder in new tab)", "locked"),
                             ("Lock (open folder is allowed)", "reset")):
            add_scaled_radiobutton(menu, tr(label), value, lock_mode,
                                   command=lambda mode=value: self.set_lock(child, mode))
        menu.tk_popup(event.x_root, event.y_root)


